"const ExcelJS = require('exceljs');
const fs = require('fs');
const path = require('path');

const targets = ['최유창', '곽재홍', '이진수', '이수연', '이지현', '우수경', '이석창'];

async function checkExcel(filePath) {
    if (!fs.existsSync(filePath)) return;
    console.log(`=== Checking ${filePath} ===`);
    const workbook = new ExcelJS.Workbook();
    try {
        await workbook.xlsx.readFile(filePath);
        workbook.eachSheet((worksheet, sheetId) => {
            worksheet.eachRow((row, rowNumber) => {
                const values = row.values;
                if (!values) return;
                const rowStr = (Array.isArray(values) ? values.join(' | ') : JSON.stringify(values));
                for (const t of targets) {
                    if (rowStr.includes(t)) {
                        console.log(`[${worksheet.name}:${rowNumber}] MATCH ${t}: ${rowStr}`);
                    }
                }
            });
        });
    } catch (e) {
        console.error(`Error reading ${filePath}:`, e.message);
    }
}

async function main() {
    await checkExcel('data/배현명_실사DB_16컬럼_전수검증완료_최종본.xlsx');
    // Let's also check all tsv files in the root dir
    const files = fs.readdirSync('.');
    for (const f of files) {
        if (f.endsWith('.tsv') || f.endsWith('.csv')) {
            const content = fs.readFileSync(f, 'utf8');
            const lines = content.split('\n');
            lines.forEach((line, idx) => {
                for (const t of targets) {
                    if (line.includes(t)) {
                        console.log(`[${f}:${idx+1}] MATCH ${t}: ${line.slice(0, 150)}`);
                    }
                }
            });
        }
    }
}

main();
"

